/* @lc app=leetcode id=3905 lang=kotlin */ class Solution { fun colorGrid(n: Int, m: Int, sources: Array<IntArray>): Array<IntArray> = IntArray(n * m).also { g -> sources.forEach { (r, c, col) -> g[r * m + c] = col } }.let { g -> generateSequence(sources.map { it[0] * m + it[1] }) { f -> HashMap<Int, Int>().also { cand -> f.forEach { u -> listOf(u / m + 1 to u % m, u / m - 1 to u % m, u / m to u % m + 1, u / m to u % m - 1).filter { (a, b) -> a in 0 until n && b in 0 until m && g[a * m + b] == 0 }.forEach { (a, b) -> cand.merge(a * m + b, g[u]) { x, y -> maxOf(x, y) } } } }.let { cand -> cand.forEach { (v, c) -> g[v] = c }.let { cand.keys.toList() } }.takeIf { it.isNotEmpty() } }.count().let { Array(n) { r -> IntArray(m) { c -> g[r * m + c] } } } } }